#!/usr/bin/env python3

# --- IMPORTS & THEIR PURPOSES ---
import rclpy                                      # The core ROS 2 Python library
from rclpy.node import Node                       # Allows us to create a ROS 2 "Node" (a worker process)
from sensor_msgs.msg import PointCloud2           # The specific ROS 2 message type for 3D LiDAR data
import sensor_msgs_py.point_cloud2 as pc2         # A helper tool to translate ROS data into standard Python numbers

import paho.mqtt.client as mqtt                   # The MQTT library (The "Radio Tower" we discussed)
import open3d as o3d                              # The heavy-duty 3D math library (The "Editor")
import numpy as np                                # Fast math for arrays of numbers
import json                                       # To package our data neatly before sending it over the network

class LidarMqttBridge(Node):
    def __init__(self):
        # 1. Initialize the Node with a name so we can find it in the ROS network
        super().__init__('lidar_mqtt_bridge')

        # 2. Setup the ROS 2 Subscriber (The "Listener")
        # We listen to a PointCloud topic. (We will use a generic '/pointcloud' for now).
        # The '10' is the queue size. If we get data faster than we can process it, keep 10 in line, drop the rest.
        self.subscription = self.create_subscription(
            PointCloud2,
            '/pointcloud', 
            self.lidar_callback,
            10
        )

        # 3. Setup the MQTT Client (The "Broadcaster")
        self.mqtt_client = mqtt.Client()
        
        # Connect to the local MQTT broker running on your Asus laptop (localhost)
        # Port 1883 is the universal standard port for MQTT traffic.
        try:
            self.mqtt_client.connect("127.0.0.1", 1883, 60)
            self.get_logger().info("Successfully connected to MQTT Broker!")
        except Exception as e:
            self.get_logger().error(f"Failed to connect to MQTT: {e}")

        # 4. Filter Parameters
        # Voxel size determines how aggressive the compression is. 
        # 0.1 means "compress everything inside a 10cm x 10cm x 10cm cube into a single dot."
        self.voxel_size = 0.1  

    def lidar_callback(self, msg):
        """
        This function fires automatically EVERY TIME the robot sends a new PointCloud frame.
        """
        # STEP A: Extract the raw dots
        # pc2.read_points pulls the X, Y, Z coordinates out of the complex ROS message
        # We skip NaNs (corrupted/infinite dots where the laser hit the sky or failed)
        raw_points = list(pc2.read_points(msg, field_names=("x", "y", "z"), skip_nans=True))
        
        # If the scan is empty, do nothing
        if not raw_points:
            return

        # STEP B: Convert to Open3D Format
        # Open3D requires data to be in a very specific mathematical array format (Numpy)
        numpy_points = np.array(raw_points)
        o3d_cloud = o3d.geometry.PointCloud()
        o3d_cloud.points = o3d.utility.Vector3dVector(numpy_points)

        # STEP C: The Compression (Voxel Downsampling)
        # This is where we solve the "15,000 points crashing the computer" problem.
        # It overlays a grid and merges duplicate/dense points.
        downsampled_cloud = o3d_cloud.voxel_down_sample(voxel_size=self.voxel_size)
        
        # Pull the compressed dots back out into a standard list
        compressed_points = np.asarray(downsampled_cloud.points).tolist()

        # STEP D: Package and Transmit
        # We convert the list of dots into a JSON string (text format)
        payload = json.dumps({"points": compressed_points})

        # Publish to the MQTT topic "ascar/lidar"
        # qos=0 means "Fire and forget." If a packet drops over Wi-Fi, we don't care, 
        # because a new one is coming in 100 milliseconds anyway.
        self.mqtt_client.publish("ascar/lidar", payload, qos=0)

        # Print a status to the terminal so you know it's working
        self.get_logger().info(f"Compressed {len(raw_points)} dots down to {len(compressed_points)} dots. Sent via MQTT.")

def main(args=None):
    # This is the entry point that boots up the ROS 2 system
    rclpy.init(args=args)
    
    # Create our bridge node
    bridge_node = LidarMqttBridge()
    
    # 'spin' means "keep this script running forever, listening for new data"
    try:
        rclpy.spin(bridge_node)
    except KeyboardInterrupt:
        pass # Allow the user to press Ctrl+C to stop the script cleanly
    
    # Clean shutdown
    bridge_node.destroy_node()
    rclpy.shutdown()

if __name__ == '__main__':
    main()